export const newProject=()=>({id:`${new Date().toLocaleDateString('sv-SE').replaceAll('-','')}-${crypto.randomUUID().slice(0,8)}`,title:'새 외근 기록',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),items:[],report:'',feedback:''});
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function templateReport(p,settings){return `${p.title}\n외근 보고서\n\n작성일: ${new Date(p.createdAt).toLocaleDateString('ko-KR')}\n작업 번호: ${p.id}\n\n1. 현장 확인 내용\n${p.items.map((x,i)=>`\n[기록 ${i+1} · ${{image:'사진',video:'영상',audio:'음성',note:'메모'}[x.type]||'기록'}]\n${x.memo?.trim()||'확인 내용 입력 필요'}${x.audio?'\n음성 메모 첨부 (본문은 메모를 기준으로 작성)':''}`).join('\n')}\n\n2. 후속 조치\n확인이 필요한 사항과 담당자, 조치 기한을 입력하세요.${p.feedback?`\n\n재작성 요청 메모: ${p.feedback}`:''}\n\n첨부: 사진 ${Math.min(settings.photos,p.items.filter(x=>x.type==='image').length)}장\n※ 기본 양식 초안입니다. 사실관계와 후속 조치를 확인해 주세요.`;}
export function validateProject(p){if(!p||typeof p.id!=='string'||typeof p.title!=='string'||!Array.isArray(p.items)||p.items.length>500)throw Error('올바른 백업 파일이 아닙니다.');for(const x of p.items){if(!['image','video','audio','note'].includes(x.type)||typeof x.id!=='string')throw Error('기록 형식이 올바르지 않습니다.');for(const k of ['data','audio'])if(x[k]&&!/^data:(image\/(jpeg|png|webp|gif)|video\/(webm|mp4|ogg)|audio\/(webm|mp4|ogg|mpeg|wav))([;,])/.test(x[k]))throw Error('지원하지 않는 미디어 형식입니다.');}return {...p,report:String(p.report||''),feedback:String(p.feedback||'')};}
